import "core-js/modules/es6.number.constructor";
/*
*部门、单位、班组联动下拉菜单 by sunq 2024年4月28日
* */
import { getDeptLzayList } from "@/api/system/dept";
import { getGroupDictList } from "@/api/system/usergroup";
export default {
  name: 'xtTreeLzaySelect',
  props: {
    isUserUnit: {
      // 是否只显示所在公司单位
      type: Boolean,
      default: true
    },
    formValue: {
      // 此处有个能是单位Name、部门Name、班组Name ，后续根据Name进行联动下一级菜单
      type: String,
      default: ''
    },
    unitId: {
      type: String,
      // 此处是单位ID，部门下拉框时必填
      default: ''
    },
    deptId: {
      type: String,
      // 此处是部门ID，班组下拉框时必填
      default: ''
    },
    disabled: {
      // 是否禁用
      type: Boolean,
      default: false
    },
    placeholder: {
      // el-input 提示文字
      type: String
    },
    treeData: {
      // 下拉菜单数据，根据前端菜单需要是否传值 一般用于单位下拉数据加载。
      type: Array,
      default: null
    },
    selectType: {
      // 下拉数据类型，可能是单位（'CORP'）、部门（'DEPT'）、班组（'GROUP'）
      type: String,
      default: ''
    },
    showFullName: {
      //是否展示全名
      type: Boolean,
      default: true
    },
    formIndex: {
      type: Number,
      default: -1
    },
    defaultProps: {
      type: Object,
      // eslint-disable-next-line vue/require-valid-default-prop
      default: {
        label: 'fullName',
        value: 'id',
        leaf: 'hasChildren',
        disabled: 'disabled'
      }
    },
    selEverNode: {
      //是否点击任意节点都触发回调
      type: Boolean,
      default: true
    }
  },
  data: function data() {
    return {
      loading: false,
      //加载提示

      ishandlePopver: false
    };
  },
  watch: {
    'unitId': function unitId(newVal, oldVal) {
      //单位ID改变 重新加载部门下拉列表
      if (this.selectType === 'DEPT') {
        this.requestDeptList();
      }
    },
    'deptId': function deptId(newVal, oldVal) {
      if (this.selectType === 'GROUP') {
        this.requestGroupList();
      }
    }
  },
  mounted: function mounted() {
    var _this = this;
    setTimeout(function () {
      _this.initData();
    }, 200);
  },
  methods: {
    initData: function initData() {
      var _this2 = this;
      if (this.selectType === 'CORP') {
        //当前是单位下拉框
        if (!this.treeData || this.treeData.length == 0) {
          if (!this.isUserUnit) {
            //请求单位下拉框数据
            this.loading = true;
            getDeptLzayList({
              type: this.selectType
            }).then(function (res) {
              _this2.loading = false;
              _this2.treeData = res.data;
            }).catch(function (err) {
              _this2.loading = false;
            });
          } else {
            var uls = JSON.parse(JSON.stringify(this.$store.state.user.userUnitList));
            this.initUserUnit(uls);
            this.treeData = uls;
          }
        }
      } else if (this.selectType === 'DEPT') {
        //当前是部门下拉框菜单，根据单位ID请求部门下拉框数据
        this.requestDeptList();
      } else if (this.selectType === 'GROUP') {
        //当前是班组下拉框菜单，根据部门ID请求班组下拉框数据
        this.requestGroupList();
      }
    },
    //只加载单位
    initUserUnit: function initUserUnit(list) {
      for (var i = list.length - 1; i >= 0; i--) {
        if (list[i].type != 'CORP') {
          list.splice(i, 1);
        }
        if (list[i] && list[i].children) {
          this.initUserUnit(list[i].children);
        }
      }
    },
    requestDeptList: function requestDeptList() {
      var _this3 = this;
      if (!this.isEmpty(this.unitId)) {
        this.loading = true;
        getDeptLzayList({
          type: this.selectType,
          parentId: this.unitId
        }).then(function (res) {
          _this3.treeData = res.data;
          _this3.loading = false;
        }).catch(function (err) {
          _this3.loading = false;
        });
      } else {
        this.treeData = [];
      }
    },
    requestGroupList: function requestGroupList() {
      var _this4 = this;
      if (!this.isEmpty(this.deptId)) {
        this.loading = true;
        getGroupDictList({
          deptId: this.deptId || this.userInfo.deptId
        }).then(function (res) {
          _this4.loading = false;
          _this4.treeData = res.data;
        }).catch(function (err) {
          _this4.loading = false;
        });
      } else {
        this.treeData = [];
      }
    },
    filterNodeMethod: function filterNodeMethod(value, data, node) {
      if (data.type === this.selectType) {
        return true;
      }
      return false;
    },
    nodeExpand: function nodeExpand(data, node, dom) {
      //create筛选
      this.$refs.tree.filter(this.selectType);
    },
    handlePopver: function handlePopver() {
      this.ishandlePopver = true;
      if (this.disabled) return;
      if (this.selectType === 'DEPT') {
        //如果是部门 判断是否传入了单位ID
        if (this.isEmpty(this.unitId)) {
          this.$message.error('请选择单位');
          return;
        }
      } else if (this.selectType === 'GROUP') {
        //如果是班组 判断是否传入了部门ID
        if (this.isEmpty(this.deptId)) {
          this.$message.error('请选择部门');
          return;
        }
      }
    },
    nodeClick: function nodeClick(data, node) {
      if (this.selectType === 'CORP') {
        if (!this.selEverNode) {
          if (data.children && data.children.length > 0) {
            return;
          }
        }
      }
      if (this.selectType === 'GROUP') {
        //如果是班组，因为班组和单位、部门从两个接口获取，返回的字段名称不一致
        data.fullName = data.groupName;
      }
      this.$emit("getTreeItem", data, this.formIndex);
      if (this.selectType !== 'CORP') {
        this.$refs.e_sel.visible = false;
      }
    },
    getName: function getName(data) {
      if (this.selectType === 'GROUP') {
        return data.groupName;
      } else {
        return this.showFullName ? data.fullName : data.deptName;
        //return data.deptName;
      }
    },
    isEmpty: function isEmpty(value) {
      if (value === '' || value == null) {
        return true;
      }
      return false;
    },
    getTypeClassName: function getTypeClassName(type) {
      if (type === 'CORP') {
        return 'el-icon-office-building';
      } else if (type === 'DEPT') {
        return 'el-icon-film';
      } else if (type === 'GROUP') {
        return 'el-icon-help';
      }
      return null;
    },
    getPlaceHolder: function getPlaceHolder(placeholder) {
      if (!this.isEmpty(placeholder)) {
        return;
      }
      if (this.selectType === 'CORP') {
        return '请选择单位名称';
      } else if (this.selectType === 'DEPT') {
        return '请选择部门名称';
      } else if (this.selectType === 'GROUP') {
        // return '请选择班组名称！';
        return '';
      }
    },
    clearClick: function clearClick() {
      var tItem = JSON.parse(JSON.stringify(this.treeData[0]));
      for (var tItemKey in tItem) {
        tItem[tItemKey] = null;
      }
      this.$emit("getTreeItem", tItem, 0);
    }
  }
};
